"""Third-party verification of ProvenMark evidence bundles. Needs no secret key: only the evidence JSON, the
suspect file (copy evidence) or the original data and recorded predictions (training evidence), and the owner's
public key. Checks: release-record signature, revealed subkey == signed commitment, file / prediction digests,
recomputation of every reported statistic. Format specification: docs/FORMATS.md.
"""
from __future__ import annotations

import numpy as np
from . import core, integrity
from .keys import commitment


UNPINNED_NOTE = ("no owner public key given: the signature was checked only against the key embedded in the bundle, "
                 "and anyone can sign a record with their own key; pass the owner's public key, obtained independently")


def _num(x) -> bool:
    return isinstance(x, (int, float)) and not isinstance(x, bool)


def _close(recomputed, reported, rtol, atol=0.0) -> bool:
    """Reported value present, numeric and equal to the recomputed one (a missing or non-numeric value fails)."""
    return _num(reported) and bool(np.isclose(recomputed, reported, rtol=rtol, atol=atol))


def verify(ev: dict, suspect_df, suspect_sha256: str, public_key: bytes | None = None, rtol: float = 1e-6) -> dict:
    checks = []

    def add(name, ok, **kw):
        checks.append({"check": name, "ok": bool(ok), **kw})

    rel = ev["release_record"]
    add("release_signature", integrity.verify_manifest_signature(rel, public_key),
        signer_key_id=rel["signature"]["key_id"], pinned=public_key is not None)
    add("signer_pinned", public_key is not None, note=None if public_key is not None else UNPINNED_NOTE)
    params = rel["manifest"]["extra"]["params"]
    keys = {m: bytes.fromhex(h) for m, h in ev["revealed_subkeys"].items()}
    for m, k in keys.items():
        add(f"commitment:{m}", commitment(k) == params["commitments"].get(m))
    add("suspect_file_hash", suspect_sha256 == ev["suspect_sha256"], expected=ev["suspect_sha256"], actual=suspect_sha256)
    # every method of the signed release must be revealed, recomputed and reported -- a method left out could hide a
    # weak result, and a reported method without a recomputation would be taken on trust
    signed_m, revealed_m, reported_m = set(params["methods"]), set(keys), set(ev["result"]["methods"])
    add("methods_complete", signed_m == revealed_m == reported_m, signed=sorted(signed_m), revealed=sorted(revealed_m),
        reported=sorted(reported_m))
    res = core.detect_with_keys(suspect_df, keys, params, ev.get("max_shift", 0))
    for m in sorted(reported_m | set(res)):
        v = ev["result"]["methods"].get(m)
        if v is None or m not in res or v.get("z") is None or v.get("p") is None:
            note = ("no detector for this method in this installation" if core.detector_module(m) is None
                    else "reported without a recomputable statistic, or recomputed but not reported")
            add(f"recomputed:{m}", False, note=note)
            continue
        z, p = float(res[m]["z"]), float(res[m]["p"])
        add(f"recomputed_z:{m}", _close(z, v["z"], rtol, 1e-9), reported=v["z"], recomputed=z)
        add(f"recomputed_p:{m}", _close(p, v["p"], rtol), reported=v["p"], recomputed=p)
    # the decision is recomputed, never taken from the bundle: Fisher over the RECOMPUTED p-values, Bonferroni over the
    # number of licensees screened (declared by the owner), compared with alpha
    r = ev["result"]
    n_screen = r.get("licensees_screened")
    alpha = ev.get("alpha")
    valid_n = isinstance(n_screen, int) and not isinstance(n_screen, bool) and n_screen >= 1
    scr = ev.get("screening")
    add("licensees_screened", valid_n and (not scr or scr.get("licensees_screened") == n_screen),
        declared=n_screen, note="declared by the owner; a third party cannot check how many licensees were screened")
    valid_alpha = _num(alpha) and 0 < alpha < 1
    add("alpha_valid", valid_alpha, alpha=alpha)
    comb = core.combine(res)
    if "decision_methods" in r:
        add("decision_methods", sorted(r["decision_methods"]) == comb["decision_methods"],
            reported=r["decision_methods"], recomputed=comb["decision_methods"], info_only=comb["info_only"])
    fam = float(min(1.0, comb["p_fisher"] * (n_screen if valid_n else 1)))
    supported = bool(valid_n and valid_alpha and fam < alpha)
    add("recomputed_p_fisher", _close(comb["p_fisher"], r.get("p_fisher"), rtol),
        reported=r.get("p_fisher"), recomputed=comb["p_fisher"])
    add("recomputed_familywise_p", _close(fam, r.get("familywise_p"), rtol),
        reported=r.get("familywise_p"), recomputed=fam)
    add("recomputed_conclusion", r.get("supported") is supported, reported=r.get("supported"), recomputed=supported)
    ok = all(c["ok"] for c in checks)
    return {"verified": ok, "checks": checks, "claim_supported": bool(ok and supported), "familywise_p": fam,
            "reported_familywise_p": r.get("familywise_p")}


# ---------------------------------------------------------------------------------------------------------------
# Training-use evidence from a keyed delivery holdout
# ---------------------------------------------------------------------------------------------------------------
def _sha_array(a: np.ndarray) -> str:
    import hashlib
    return hashlib.sha256(np.ascontiguousarray(np.asarray(a, dtype="<f8")).tobytes()).hexdigest()


def verify_training(ev: dict, original_df, predictions: np.ndarray, public_key: bytes | None = None,
                    rtol: float = 1e-9, reference_seed: int = 1) -> dict:
    from . import holdout as ho
    checks = []

    def add(name, ok, **kw):
        checks.append({"check": name, "ok": bool(ok), **kw})

    rel = ev["release_record"]
    add("release_signature", integrity.verify_manifest_signature(rel, public_key),
        signer_key_id=rel["signature"]["key_id"], pinned=public_key is not None)
    add("signer_pinned", public_key is not None, note=None if public_key is not None else UNPINNED_NOTE)
    params = rel["manifest"]["extra"]["params"]
    hp = params["holdout"]
    key = bytes.fromhex(ev["revealed_holdout_key"])
    add("commitment:holdout", commitment(key) == params["commitments"].get("holdout"))
    parent = rel["manifest"]["extra"].get("parent_merkle_root")
    if parent:
        add("original_matches_signed_root", integrity.fingerprint(original_df)["merkle_root"] == parent)
    else:
        add("original_matches_signed_root", False, note="release record has no parent manifest (seal the original first)")
    predictions = np.asarray(predictions, float)
    add("predictions_sha256", _sha_array(predictions) == ev["predictions_sha256"])
    qm = ev["queries"]
    q = ho.make_queries(original_df, hp, qm["columns"], qm["context"], qm["horizon"], qm["per_block"], qm["seed"])
    add("predictions_shape", predictions.shape == q["fut"].shape)
    recipe = hp.get("reference")
    comps = ho.reference_components(recipe)
    learned = any(c.get("type") != "ridge" for c in comps)
    res_ = ev["result"]
    n_screen, alpha, n = res_.get("licensees_screened"), ev.get("alpha"), res_.get("n_decoys")
    valid_n = isinstance(n_screen, int) and not isinstance(n_screen, bool) and n_screen >= 1
    add("licensees_screened", valid_n and (not ev.get("screening")
                                           or ev["screening"].get("licensees_screened") == n_screen),
        declared=n_screen, note="declared by the owner; a third party cannot check how many licensees were screened")
    valid_alpha = _num(alpha) and 0 < alpha < 1
    add("alpha_valid", valid_alpha, alpha=alpha)
    valid_decoys = isinstance(n, int) and not isinstance(n, bool) and n >= 1
    add("n_decoys_valid", valid_decoys, n_decoys=n)
    fam, supported = None, False
    if predictions.shape == q["fut"].shape and valid_decoys:
        losses = ho.losses_from_predictions(q, predictions, hp["n_blocks"])
        # learned reference: the VERIFIER trains its own copy from the committed recipe (own seed); results are
        # statistically, not bit-for-bit, reproducible, so the check is whether the claim still holds
        refs = [ho.reference_losses(original_df, hp, q, c, seed=reference_seed if c.get("type") != "ridge" else 0)
                for c in comps]
        r = ho.best_of_test(losses, hp, key, refs, n, seed=0)
        pc = []
        for c in ev.get("conditioning", []):
            ok_c = c.get("release_record") is not None
            ck = bytes.fromhex(c["revealed_holdout_key"])
            if ok_c:
                orel = c["release_record"]
                op = orel["manifest"]["extra"]["params"]
                ok_c = (integrity.verify_manifest_signature(orel, public_key)
                        and commitment(ck) == op["commitments"].get("holdout")
                        and op.get("holdout", {}).get("n_blocks") == hp["n_blocks"]
                        and op.get("holdout", {}).get("q") == hp["q"]
                        and orel["manifest"]["extra"].get("parent_merkle_root") == parent)
            add(f"conditioning_key:{c['licensee']}", ok_c,
                note=None if ok_c else "no valid signed release record matching the revealed key")
            pc.append(ho.best_of_test(losses, hp, key, refs, n, seed=0, mask=ho.delivered_mask(hp, ck))["p_perm"])
        # the decision is recomputed by the verifier, never taken from the bundle
        fam = float(min(1.0, max([r["p_perm"]] + pc) * (n_screen if valid_n else 1)))
        supported = bool(valid_n and valid_alpha and fam <= alpha)
        if learned:
            add("verifier_reference_supports_claim", supported == (res_.get("supported") is True),
                reported_p=res_.get("p"), verifier_p=r["p_perm"], verifier_familywise_p=fam,
                reference_seed=reference_seed)
            fair = min((ho.reference_fairness(rf, hp, key, n) for rf in refs), key=lambda f: f["p_fair"])
            add("verifier_reference_fairness", fair["p_fair"] >= 0.01, p_fair=fair["p_fair"])
        else:
            add("recomputed_p", _close(r["p_perm"], res_.get("p"), rtol), reported=res_.get("p"), recomputed=r["p_perm"])
            add("recomputed_familywise_p", _close(fam, res_.get("familywise_p"), rtol),
                reported=res_.get("familywise_p"), recomputed=fam)
            add("recomputed_z", _close(r["z_vs_decoys"], res_.get("z"), 1e-6, 1e-9),
                reported=res_.get("z"), recomputed=r["z_vs_decoys"])
            add("recomputed_conclusion", res_.get("supported") is supported, reported=res_.get("supported"),
                recomputed=supported)
        fp = res_.get("reference_fairness_p", 1.0)
        add("owner_reference_fairness", _num(fp) and fp >= 0.01, p_fair=fp)
    ok = all(c["ok"] for c in checks)
    # learned reference: the verifier's own p differs from the owner's in the last digits; report the verifier's value
    return {"verified": ok, "checks": checks, "claim_supported": bool(ok and supported), "familywise_p": fam,
            "reported_familywise_p": res_.get("familywise_p")}
